test:
assert_eq!(dedup_sorted(vec![3,1,2,3,1]), vec![1,2,3]);
assert_eq!(dedup_sorted(vec![]), vec![]);
assert_eq!(dedup_sorted(vec![5,5,5]), vec![5]);

let mut c = Counter::new();
c.incr();
c.incr();
c.incr();
assert_eq!(c.value(), 3);

assert!(is_palindrome("A man a plan a canal Panama"));
assert!(is_palindrome(""));
assert!(!is_palindrome("hello"));

let m = word_count("a b a c a");
assert_eq!(m["a"], 3);
assert_eq!(m["b"], 1);
assert_eq!(m["c"], 1);

assert_eq!(max_item(&[3,7,2]), Some(7));
assert_eq!(max_item::<i32>(&[]), None);
assert_eq!(max_item(&[1.5, 2.5, 0.5]), Some(2.5));

assert_eq!(rotate_left(&[1,2,3,4,5], 2), vec![3,4,5,1,2]);
assert_eq!(rotate_left(&[1,2,3], 0), vec![1,2,3]);
assert_eq!(rotate_left(&[1,2,3], 4), vec![2,3,1]);
assert_eq!(rotate_left(&[], 3), vec![]);

assert!(!is_prime(0));
assert!(!is_prime(1));
assert!(is_prime(2));
assert!(is_prime(13));
assert!(!is_prime(15));
assert!(is_prime(97));

assert_eq!(two_sum(&[2,7,11,15], 9), Some((0,1)));
assert_eq!(two_sum(&[3,2,4], 6), Some((1,2)));
assert_eq!(two_sum(&[1,2,3], 100), None);

assert_eq!(merge_sorted(&[1,3,5], &[2,4,6]), vec![1,2,3,4,5,6]);
assert_eq!(merge_sorted(&[], &[1]), vec![1]);
assert_eq!(merge_sorted(&[1,2], &[]), vec![1,2]);

assert_eq!(most_common_char("aabbbc"), Some('b'));
assert_eq!(most_common_char(""), None);
assert_eq!(most_common_char("zzz"), Some('z'));

let mut s: Stack<i32> = Stack::new();
s.push(1);
s.push(2);
s.push(3);
assert_eq!(s.pop(), Some(3));
assert_eq!(s.len(), 2);
assert_eq!(s.pop(), Some(2));

assert_eq!(median(&[1.0, 3.0, 2.0]), Some(2.0));
assert_eq!(median(&[1.0, 2.0, 3.0, 4.0]), Some(2.5));
assert_eq!(median(&[]), None);
